// We use the built-in Verus `Vec<T>` and integer types.
// No external imports are necessary for this simple example.

verus! {

    /// Given two vectors `a` and `b` of 8-bit unsigned integers of equal length,
    /// returns a new vector `result` of the same length such that
    /// for each valid index `i`, `result[i] == a[i] & b[i]`.
    ///
    /// Specification:
    ///   - Requires: a.len() == b.len()
    ///   - Ensures: result.len() == a.len()
    ///   - Ensures: for all i < a.len(), result[i] == a[i] & b[i].
    pub fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
        // Precondition: both inputs have the same length
        requires(a.len() == b.len());
        // Postconditions:
        ensures(|result: &Vec<u8>| result.len() == a.len());
        ensures(|result: &Vec<u8>| forall(|i: usize| i < a.len() ==> result[i] == a[i] & b[i]));

        let n = a.len();

        // Allocate an empty result vector and reserve capacity n.
        let mut result: Vec<u8> = Vec::new();
        result.reserve(n);

        // Index variable
        let mut i: usize = 0;

        // Loop to fill in result
        while i < n {
            // Invariants to maintain during the loop:
            // 1) 0 <= i <= n
            invariant(i <= n);
            // 2) result.len() == i
            invariant(result.len() == i);
            // 3) For all j < i, result[j] == a[j] & b[j]
            invariant(forall(|j: usize| j < i ==> result[j] == a[j] & b[j]));
            // We need a decreases clause so Verus can prove termination:
            decreases(n - i);

            // Compute the bitwise AND of a[i] and b[i]
            let ai = a[i];
            let bi = b[i];
            let ci = ai & bi;

            // Append to the result vector
            result.push(ci);

            // Advance the loop index
            i += 1;
        }

        // At this point, i == n, so result.len() == n, and by the invariant,
        // for all j < n, result[j] == a[j] & b[j].
        result
    }

    // A simple test to drive the verifier. This is not executed at runtime.
    #[verifier::proof]
    pub fn test_bitwise_and() {
        let a = vec![0b1010_u8, 0b1100_u8, 0b1111_u8];
        let b = vec![0b0101_u8, 0b1010_u8, 0b0011_u8];
        let r = bitwise_and(a.clone(), b.clone());
        assert(r.len() == a.len());
        assert(r[0] == 0b1010_u8 & 0b0101_u8);
        assert(r[1] == 0b1100_u8 & 0b1010_u8);
        assert(r[2] == 0b1111_u8 & 0b0011_u8);
    }

}